public static boolean canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Initialize a visited array to keep track of the visited n-tersections
        boolean[] visited = new boolean[n * n];

        // Initialize the queue with the starting n-tersection
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(start[0] * n + start[1]);
        visited[start[0] * n + start[1]] = true;

        // Loop until the queue is empty
        while (!queue.isEmpty()) {
            // Get the current n-tersection from the queue
            int current = queue.poll();

            // If the current n-tersection is the ending n-tersection, return true
            if (current == end[0] * n + end[1]) {
                return true;
            }

            // Loop through all the n-tersections that can be reached from the current n-tersection
            for (int i = 0; i < n; i++) {
                // Get the n-tersection that can be reached from the current n-tersection
                int next = current + paths[current / n][i];

                // If the n-tersection is not visited and is not out of bounds, mark it as visited and add it to the queue
                if (!visited[next] && next >= 0 && next < n * n) {
                    visited[next] = true;
                    queue.offer(next);
                }
            }
        }

        // If the queue is empty and the ending n-tersection was not reached, return false
        return false;
    }

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    int len1 = word1.length();
    int len2 = word2.length();
    for (int i = 0; i < len1 && i < len2; i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }
    int denom = len1 + len2;
    if (denom == 0) {
        return "0";
    }
    int num = commonLetters;
    int gcd = gcd(num, denom);
    num /= gcd;
    denom /= gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + num + "/" + denom;
}

public static String convertDatesToWeekdays(String date) {
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String[] dateArray = date.split(" ");
    int month = Integer.parseInt(dateArray[0]);
    int day = Integer.parseInt(dateArray[1]);
    int year = Integer.parseInt(dateArray[2]);
    Calendar calendar = Calendar.getInstance();
    calendar.set(Calendar.MONTH, month - 1);
    calendar.set(Calendar.DAY_OF_MONTH, day);
    calendar.set(Calendar.YEAR, year);
    int weekday = calendar.get(Calendar.DAY_OF_WEEK);
    return months[month - 1] + " " + day + ", " + year + " is " + weekdays[weekday - 1];
}

