        int end = nums.length - 1;
        int mid;
        int rotationIndex = findRotationIndex(nums);

        while (start <= end) {
            mid = (start + end) / 2;
            int rotatedMid = (mid + rotationIndex) % nums.length;
            if (nums[rotatedMid] == target) {
                return rotatedMid;
