    for (int num : nums) {
        if (!countMap.containsKey(num)) {
            countMap.put(num, 1);
        } else {
            countMap.put(num, countMap.get(num) + 1);
        }
    }
    for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            return entry.getKey();
        }
    }
    return -1;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    for (int num = low; num <= high; num++) {
        boolean isSteppingNumber = true;
        String numStr = String.valueOf(num);
        for (int i = 0; i < numStr.length() - 1; i++) {
            int digit = numStr.charAt(i) - '0';
            int nextDigit = numStr.charAt(i + 1) - '0';
            if (Math.abs(digit - nextDigit) != 1) {
                isSteppingNumber = false;
                break;
            }
        }
        if (isSteppingNumber) {
            steppingNumbers.add(num);
        }
    }
    return steppingNumbers;
}

