    int i2 = 0, i3 = 0, i5 = 0;
    int nextUglyNumber = 1;
    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumber[i2] * 2, Math.min(uglyNumber[i3] * 3, uglyNumber[i5] * 5));
        nextUglyNumber = min;
        while (uglyNumber[i2] * 2 <= nextUglyNumber) {
